// The drums and simple voices of synths.lib as modules, generated by build-faust-library-modules.mjs as the
// filters (faust-filter-modules.mjs): the functions take their settings as arguments, each module gives them
// an interface made for music.
//
// - Gate: a button; a gate dropped on it (⇐ drive: a sequencer, a clock) triggers the sound.
// - Freq in Hz on a log scale and Pitch (0.1 per octave) on the pitched ones: the pitch transposes the
//   frequency, so that a sequencer dropped on Pitch (+ add) plays the notes from the frequency set.
// - Times in ms on a log scale (the envelopes of the library are linear: Decay is the time to silence); no
//   smoothing.
//
// Family: Lib drums (in FAUST_LIBRARY_FAMILIES).

const GATE = `gate = button("[0]Gate");`;
const FREQ = (deflt, min, max) => `freq = hslider("[1]Freq[unit:Hz][scale:log]", ${deflt}, ${min}, ${max}, 0.1) * pow(2, 10 * pitch);
pitch = hslider("[2]Pitch[unit:pitch]", 0, -1, 1, 0.0001);`;
const MS = (index, label, deflt, min, max) => `hslider("[${index}]${label}[unit:ms][scale:log]", ${deflt}, ${min}, ${max}, 0.1) / 1000`;
const AUDIO = { inlets: "", outlets: "audio" };
const GATE_LINE = "Gate: triggers the sound; a gate dropped on it (a sequencer, a clock) plays it";
const PITCH_LINE = "Freq in Hz; Pitch transposes it, 0.1 per octave: a sequencer dropped on Pitch plays the notes from the frequency set";

export const DRUM_MODULES = [
    {
        family: "Lib drums", name: "Kick", file: "Kick", source: "sy.kick (synths.lib)", ...AUDIO,
        summary: [
            "Kick drum: a sine whose frequency falls from five times the frequency to the frequency, through a saturation",
            GATE_LINE, PITCH_LINE,
            "Click: the time of the fall of the frequency; Attack and Decay: the envelope, linear (Decay: to silence); Drive: the saturation (1 to 10)",
        ],
        body: `process = sy.kick(freq, click, attack, decay, drive, gate);

${GATE}
${FREQ(50, 20, 200)}
click = ${MS(3, "Click", 50, 5, 1000)};
attack = ${MS(4, "Attack", 5, 5, 400)};
decay = ${MS(5, "Decay", 500, 5, 4000)};
drive = hslider("[6]Drive[scale:log]", 1, 1, 10, 0.01);`,
    },
    {
        family: "Lib drums", name: "Clap", file: "Clap", source: "sy.clap (synths.lib)", ...AUDIO,
        summary: [
            "Hand clap: a white noise through four staggered envelopes and a resonant low pass filter",
            GATE_LINE,
            "Tone: the cutoff of the filter (400 to 3500 Hz); Attack and Decay: added to the envelopes of the claps",
        ],
        body: `process = sy.clap(tone, attack, decay, gate);

${GATE}
tone = hslider("[1]Tone[unit:Hz][scale:log]", 1500, 400, 3500, 1);
attack = hslider("[2]Attack[unit:ms]", 0, 0, 200, 0.1) / 1000;
decay = ${MS(3, "Decay", 100, 1, 4000)};`,
    },
    {
        family: "Lib drums", name: "Hi-Hat", file: "HiHat", source: "sy.hat (synths.lib)", ...AUDIO,
        summary: [
            "Hi-hat: two sines in phase modulation driven by a noise, through a resonant low pass filter",
            GATE_LINE, PITCH_LINE,
            "Tone: the cutoff of the filter (800 Hz to 18 kHz); Attack and Decay: the envelope, linear (Decay: to silence)",
        ],
        body: `// the resonance of the filter of sy.hat (1.214) takes it to 1.29: kept within [-1, 1] by 0.75
process = sy.hat(freq, tone, attack, decay, gate) * 0.75;

${GATE}
${FREQ(1000, 317, 3170)}
tone = hslider("[3]Tone[unit:Hz][scale:log]", 8000, 800, 18000, 1);
attack = ${MS(4, "Attack", 5, 5, 200)};
decay = ${MS(5, "Decay", 100, 5, 4000)};`,
    },
    {
        family: "Lib drums", name: "Pop Drum", file: "PopDrum", source: "sy.popFilterDrum (synths.lib)", ...AUDIO,
        summary: [
            "Pop drum: a burst of noise of 2 ms through a resonant band pass filter, which rings at the frequency",
            GATE_LINE, PITCH_LINE,
            "Q: the resonance of the filter, how long it rings (5: a drum); the level is kept about the same whatever the frequency",
        ],
        body: `// the level of the burst through the filter grows with the frequency: kept about the same by 1500/freq
process = sy.popFilterDrum(freq, q, gate) * 1500 / freq;

${GATE}
${FREQ(150, 20, 5000)}
q = hslider("[3]Q[scale:log]", 5, 1, 100, 0.01);`,
    },
    {
        family: "Lib drums", name: "Additive Drum", file: "AdditiveDrum", source: "sy.additiveDrum (synths.lib)", ...AUDIO,
        summary: [
            "Additive drum: sines at the frequencies of the modes of a membrane or of a bar, each with its envelope",
            GATE_LINE, PITCH_LINE,
            "Mode: membrane (the modes of a circular membrane, 1, 1.59, 2.14, 2.30...) or bar (a free bar, 1, 2.76, 5.40, 8.93)",
            "Damping: how much faster the upper modes die (0 to 1); Attack and Release: the envelope",
        ],
        body: `process = sy.additiveDrum(freq, (1, 1.594, 2.136, 2.296, 2.653, 2.918, 3.156, 3.501), (1, 0.8, 0.6, 0.5, 0.4, 0.35, 0.3, 0.25), damping, attack, release, gate) / 4,
    sy.additiveDrum(freq, (1, 2.756, 5.404, 8.933), (1, 0.6, 0.4, 0.25), damping, attack, release, gate) / 2.25 : ba.selectn(2, mode);

mode = hslider("[1]Mode[style:menu{'membrane':0;'bar':1}]", 0, 0, 1, 1);
${GATE}
freq = hslider("[2]Freq[unit:Hz][scale:log]", 120, 20, 2000, 0.1) * pow(2, 10 * pitch);
pitch = hslider("[3]Pitch[unit:pitch]", 0, -1, 1, 0.0001);
damping = hslider("[4]Damping", 0.5, 0, 1, 0.01);
attack = ${MS(5, "Attack", 2, 1, 500)};
release = ${MS(6, "Release", 500, 10, 5000)};`,
    },
    {
        family: "Lib drums", name: "Comb String", file: "CombString", source: "sy.combString (synths.lib)", ...AUDIO,
        summary: [
            "Plucked string, the simplest one: a burst of noise of 2 ms in a comb filter tuned to the frequency",
            GATE_LINE, PITCH_LINE,
            "Decay: the time to -60 dB of the string (the module converts it to the resonance of the library: 1000 Decay Freq / (6.91 SR))",
        ],
        body: `// the resonance of sy.combString is the time constant of its feedback per period, in ms: its time to -60 dB is
// 6.91 res SR / (1000 freq); the module sets it from the decay asked. The delay line holds 1024 samples: the
// frequency is kept above SR/1000.
process = sy.combString(f, 1000 * decay * f / (6.91 * ma.SR), gate)
with {
    f = freq : max(ma.SR / 1000);
};

${GATE}
${FREQ(220, 50, 2000)}
decay = hslider("[3]Decay[unit:s][scale:log]", 2, 0.05, 20, 0.01);`,
    },
    {
        family: "Lib drums", name: "Dub Synth", file: "DubSynth", source: "sy.dubDub (synths.lib)", ...AUDIO,
        summary: [
            "Dub synth: a sawtooth through a resonant low pass filter, while the gate is held (10 ms of attack and release)",
            GATE_LINE, PITCH_LINE,
            "Cutoff and Q: the filter",
        ],
        body: `process = sy.dubDub(freq, cutoff, q, gate);

${GATE}
${FREQ(110, 20, 2000)}
cutoff = hslider("[3]Cutoff[unit:Hz][scale:log]", 1000, 20, 20000, 1);
q = hslider("[4]Q[scale:log]", 3, 0.5, 20, 0.001);`,
    },
    {
        family: "Lib drums", name: "Saw Trombone", file: "SawTrombone", source: "sy.sawTrombone (synths.lib)", ...AUDIO,
        summary: [
            "Trombone, simply: a sawtooth through a low pass filter that opens with the level, while the gate is held",
            GATE_LINE, PITCH_LINE,
            "Gain: the level, and the brightness (the cutoff goes from 50 Hz to 5 kHz with it)",
        ],
        body: `process = sy.sawTrombone(freq, gain, gate);

${GATE}
${FREQ(220, 20, 2000)}
gain = hslider("[3]Gain", 0.5, 0, 1, 0.01);`,
    },
];
